price_min = df['Crude_Oil_Price'].min()
price_max = df['Crude_Oil_Price'].max()
price_range = price_max - price_min
date_min = df['Date'].min()
date_max = df['Date'].max()
n_years = (date_max - date_min).days / 365.25
cagr = ((df['Crude_Oil_Price'].iloc[-1] / df['Crude_Oil_Price'].iloc[0]) ** (1 / n_years) - 1) * 100

# Max MoM change
max_mom_abs_idx = df['MoM_abs'].abs().idxmax()
max_mom_abs_date = df.loc[max_mom_abs_idx, 'Date']
max_mom_abs_val = df.loc[max_mom_abs_idx, 'MoM_abs']

max_mom_pct_idx = df['MoM_pct'].abs().idxmax()
max_mom_pct_date = df.loc[max_mom_pct_idx, 'Date']
max_mom_pct_val = df.loc[max_mom_pct_idx, 'MoM_pct']

# Decade stats
decade_stats = df.groupby('Decade')['Crude_Oil_Price'].agg(['mean', 'std', 'min', 'max', 'count'])
decade_stats.columns = ['Mean', 'Std', 'Min', 'Max', 'Count']
decade_highest = decade_stats['Mean'].idxmax()

# Overall volatility
overall_std = df['Crude_Oil_Price'].std()

# Descriptive stats
desc = df['Crude_Oil_Price'].describe(percentiles=[0.1, 0.25, 0.5, 0.75, 0.9])
median_price = df['Crude_Oil_Price'].median()

# Largest YoY changes
df_yoy_valid = df.dropna(subset=['YoY_pct'])
max_yoy_idx = df_yoy_valid['YoY_pct'].abs().idxmax()
